from pymongo import MongoClient
import os

# Using MongoDB Atlas as the managed NoSQL document store
client = MongoClient(os.getenv('MONGODB_ATLAS_URI'))
db = client['document_store']
collection = db['products']

def update_product_version_aware(product_id, new_price, current_version):
    """
    Perform a version-aware update on a product document
    """
    result = collection.update_one(
        {
            '_id': product_id,
            'version': current_version
        },
        {
            '$set': {
                'price': new_price,
                'updated_at': '2023-10-15T10:00:00Z'
            },
            '$inc': {
                'version': 1
            }
        }
    )

    if result.matched_count == 0:
        raise Exception("Document not found or version mismatch")

    return result.modified_count > 0

# Example usage
# update_product_version_aware("product_123", 29.99, 5)
